import { Component, HostListener } from '@angular/core';
import { AuthService } from './services/auth.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  currentYear: number = new Date().getFullYear();
  title = 'euprava-frontend';
  public imagePath = 'assets/report.png';
  public imagePath2 = 'assets/accoun.png';
  public showProfileMenu: boolean = false;

  constructor(private authService: AuthService, private router: Router) {}

  get isLoggedIn(): boolean {
    return !!localStorage.getItem('jwtToken');
  }

  toggleProfileMenu() {
    this.showProfileMenu = !this.showProfileMenu;
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    const target = event.target as HTMLElement;
    const clickedInsideMenu = target.closest('.profile-container') || target.closest('.profile-menu');
    if (!clickedInsideMenu) {
      this.showProfileMenu = false;
    }
  }

  logout() {
    this.authService.logout().subscribe(() => {
      this.router.navigate(['/login']);
    });
  }

  goToProfile() {
    this.showProfileMenu = false;
    this.router.navigate(['/profile']);
  }

  goToLicna() {
    this.showProfileMenu = false;
    this.router.navigate(['/licna']);
  }

  goToDashboard() {
    this.showProfileMenu = false;
    this.router.navigate(['/dashboard']);
  }

  goToSaobracajna() {
    this.showProfileMenu = false;
    this.router.navigate(['/vozacka']);
  }

}
<nav *ngIf="isLoggedIn" class="navbar navbar-expand-lg navbar-light bg-light shadow-sm">
  <div class="container-fluid d-flex justify-content-between align-items-center">
    <div class="d-flex align-items-center">
      <a class="navbar-brand d-flex align-items-center me-4" style="cursor: pointer;" (click)="goToDashboard()">
        <img [src]="imagePath" id="logo" alt="eUprava Logo" loading="lazy">
        <h4 class="ms-2 mb-0">eUprava</h4>
      </a>

      <a class="nav-link main-link" routerLink="/licna" id="doc-link" (click)="goToLicna()">Lična</a>
      <a class="nav-link main-link" routerLink="/saobracajna" id="doc-link" (click)="goToSaobracajna()">Saobraćajna</a>
      <a class="nav-link main-link" routerLink="/vozacka" id="doc-link">Vozačka</a>
    </div>

    <div class="position-relative">
      <a class="nav-link" style="cursor: pointer;" (click)="toggleProfileMenu()">
        <div class="profile-container">
          <img [src]="imagePath2" alt="Profile Icon" class="profile-icon">
        </div>
      </a>

      <div *ngIf="showProfileMenu" class="profile-menu shadow-lg rounded position-absolute end-0 mt-2 bg-white">
        <a class="nav-link profile-menu-item" (click)="goToProfile()">Profile</a>
        <a class="nav-link profile-menu-item" (click)="logout()">Logout</a>
      </div>
    </div>
  </div>
</nav>

<main class="page-content">
  <router-outlet></router-outlet>
</main>

<footer class="global-footer">
  <div class="footer-content">
    <div class="footer-text">
      <span class="footer-title">eUprava MUP</span>
      <span class="footer-subtitle">&copy; {{ currentYear }} Sva prava zadržana</span>
    </div>
  </div>
</footer>
